-- Passage rg6-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f0c7f22a-0c88-5440-a63c-8da729bb5b11', 'rg6-theme-summary-p06', (select id from public.skills where slug = 'read-g6-theme-summary'), null,
        '6-8', $q$Night at the Observatory$q$, $q$We climbed the hill in winter coats
to where the white dome stood.
The guide said, "Hush, and let your eyes
get used to dark." We would.

At first I only saw a few,
like salt spilled on a sheet.
Then more and more came shining through,
too many to repeat.

She turned the telescope for me.
I leaned in, cold and still,
and saw a cloud of baby stars
being born beyond the hill.

"That light left there," she told us all,
"before your town was here."
I felt as small as one grain of sand,
and yet I felt no fear.

For I had seen it, I alone,
with my own blinking eye.
A speck can still look out and learn
the secrets of the sky.

We walked back down the frozen path,
my breath a little cloud.
I did not say a single word.
My thoughts were far too loud.$q$, 'draft')
