  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('3cb7e42b-f8ef-593a-be62-ba0728e4db2a', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the story?$q$, $q$[{"text":"Learning to play the violin takes many years of practice.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Playing the melody is the only important job in an orchestra.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Best friends should always try out for the same section.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Every part of a group effort matters, even when it gets no attention.","is_correct":true}]$q$::jsonb, $q$Every part of a group effort matters, even when it gets no attention.$q$, $q$Mr. Adeyemi shows that the melody sounds thin without the harmony, and Lucia learns her quiet part makes the music full. The story says the opposite of the first choice, since the whole piece "sinks" without the harmony.$q$, 'draft', 'bd979aea-5281-595d-9d5a-52b19c1e442b')
